-- Global market prices read from the in-game market recordings (parts 2026-11-04 15:09, weapons 15:59 KST).
-- Generated; safe to run every time. A newer observation of the same item (e.g. a later recording) wins.
SET NAMES utf8mb4;
AS nv ON DUPLICATE KEY UPDATE
  price = IF(nv.observed_at >= price_global.observed_at, nv.price, price_global.price),
  source = IF(nv.observed_at >= price_global.observed_at, nv.source, price_global.source),
  observed_at = GREATEST(price_global.observed_at, nv.observed_at);
